 $('#timeline').innerHTML=ids.map((id,i)=>'<li class="'+(statuses[i]||'pending')+'"><span class="step-no">'+(statuses[i]==='done'?'✓':String(id+1).padStart(2,'0'))+'</span><div><strong>'+allSteps[id]+'</strong><small>'+(statuses[i]==='done'?'Đã thực hiện':statuses[i]==='active'?'Đang thực hiện':'Nghỉ 2 giây sau bước này')+'</small></div><span class="step-state">'+(statuses[i]==='done'?'✓':statuses[i]==='active'?'•••':'')+'</span></li>').join('');
 $('#footer-site').textContent=profile().label+' · '+ids.length+' bước';
