 $('#footer-status').innerHTML='<i class="'+(running&&!paused?'pulsing':'')+'"></i>'+ (running?(paused?'Đã tạm dừng':'Đang chạy'):phase==='done'?'Hoàn tất':phase==='stopped'?'Đã dừng':'Sẵn sàng');
