async function wait(ms,token,onTick){
 let left=ms,last=performance.now(),shown=-1;
 while(left>0){
  if(token!==runToken||!alive)throw Error('STOP');
  await new Promise(resolve=>setTimeout(resolve,30));
  if(token!==runToken||!alive)throw Error('STOP');
  const now=performance.now();if(!paused)left-=now-last;last=now;
  const sec=Math.max(0,Math.ceil(left/1000));if(onTick&&sec!==shown){shown=sec;onTick(sec);}
 }
 while(paused){if(token!==runToken||!alive)throw Error('STOP');await new Promise(r=>setTimeout(r,30));}
}
async function typeFields(fields,token){
 $('#stage-content').innerHTML=fields.map(([key,label,value])=>'<label class="mock-field">'+esc(label)+'<span id="typing-'+key+'">'+(value?'':'—')+'</span></label>').join('');
 for(const [key,label,value] of fields){
  const el=$('#typing-'+key);el.classList.add('typing');el.textContent='';
  let text='';for(const c of String(value)){await wait(profile().speed,token);text+=c;el.textContent=key==='password'||key==='pin'||key==='pin2'?'•'.repeat(text.length):text;}
  el.classList.remove('typing');
 }
}
async function previewStep(id,r,token){
 if(id===0)await typeFields([['username','Username',r.username],['password','Mật khẩu',r.password],['phone','Điện thoại',r.phone],['name','Họ tên',r.name]],token);
 else if(id===5)await typeFields([['pin','Mật khẩu rút',r.pin],['pin2','Nhập lại mật khẩu rút',r.pin]],token);
 else if(id===9)await typeFields([['name','Họ tên',r.name],['account','Số tài khoản',r.account],['city','Thành phố',r.city]],token);
 else {$('#stage-content').innerHTML='<div class="mock-click">'+icon('check')+'<strong>'+esc(id===8?r.bankInfo.Display:allSteps[id])+'</strong><small>Chạy thử trong bảng điều khiển</small></div>';await wait(220,token);}
}
async function run(recovery=null){
 if(busy())return;
 if(pendingResume&&!recovery){tab('data');toast('Có tiến trình đã lưu. Chọn Tiếp tục hoặc Bỏ tiến trình cũ trước khi chạy mới.');return;}
 parseData();
 if(!records.length||records.some(r=>r.errors.length)){tab('data');toast('Kiểm tra và sửa data trước khi bắt đầu.');return;}
 const selected=records.map(r=>({...r})),runMode=execution;
 if(runMode==='live'&&profile().origin){let expected;try{expected=new URL(profile().origin).origin;}catch{toast('URL trong cấu hình chưa hợp lệ.');return;}if(expected!==location.origin){toast('Đang mở sai tên miền so với cấu hình site.');return;}}
 phase='running';paused=false;isUnloading=false;const token=++runToken,ids=plan(),firstRow=recovery?.row||0,firstStep=recovery?.step||0;completed=firstRow*ids.length+firstStep;stepIndex=-1;logs=[];logCount=0;statuses=[];$('#log-list').innerHTML='';tab('progress');updateControls();
 const total=selected.length*ids.length;$('#progress-bar').style.width=(completed/total*100)+'%';beginProgress(selected);
 try{
  for(rowIndex=firstRow;rowIndex<selected.length;rowIndex++){
   const r=selected[rowIndex],startAt=rowIndex===firstRow?firstStep:0;pinAlreadySet=rowIndex===firstRow?!!recovery?.pinAlreadySet:false;statuses=ids.map((_,i)=>i<startAt?'done':'pending');$('#row-stat').textContent=(rowIndex+1)+' / '+selected.length;
   $('#run-title').textContent='Dòng '+String(rowIndex+1).padStart(2,'0')+' · '+(mode==='bank'?r.name:r.username);
   $('#run-desc').textContent=(r.bankInfo?r.bankInfo.Display+' · ':'')+profile().label+' · '+(runMode==='live'?'Thao tác trên website':'Chạy thử');
   stepIndex=startAt;renderTimeline();
   if(rowIndex===firstRow&&recovery?.cooldown){writeProgress('resume-wait');await wait(RESUME_DELAY_MS,token,sec=>{$('#countdown').textContent='Đã khôi phục · nghỉ '+sec+' giây rồi tiếp tục';});}
   for(stepIndex=startAt;stepIndex<ids.length;stepIndex++){
    if(token!==runToken)throw Error('STOP');
    const id=ids[stepIndex];statuses[stepIndex]='active';renderTimeline();$('#tab-count').textContent=(stepIndex+1)+'/'+ids.length;
    $('#stage-title').textContent=allSteps[id];$('#stage-tag').textContent='BƯỚC '+(id+1);$('#countdown').textContent='Đang thực hiện…';
    log('Dòng '+(rowIndex+1)+' · '+allSteps[id]);writeProgress('before',{submittedPath:null,action:null});
    if(runMode==='live')await liveStep(id,r,token);else await previewStep(id,r,token);
    writeProgress('cooldown');await wait(STEP_DELAY_MS,token,sec=>{$('#countdown').textContent='Nghỉ '+sec+' giây trước khi tiếp tục';});
    statuses[stepIndex]='done';completed++;$('#progress-bar').style.width=(completed/total*100)+'%';renderTimeline();writeProgress('before',{step:stepIndex+1,submittedPath:null,action:null});
   }
   log('Dòng '+(rowIndex+1)+' · Hoàn tất'+(runMode==='preview'?' chạy thử.':'.'));
   if(runMode==='live'&&rowIndex<selected.length-1){paused=true;writeProgress('between-records',{row:rowIndex+1,step:0,pinAlreadySet:false});$('#run-desc').textContent='Chuẩn bị tài khoản / form cho dòng '+(rowIndex+2)+', rồi nhấn Tiếp tục. Có thể thu nhỏ viptool để thao tác.';$('#countdown').textContent='Chờ bạn chuẩn bị phiên cho dòng tiếp theo';updateControls();await wait(30,token);}
  }
  phase='done';clearProgress();stepIndex=ids.length-1;$('#run-title').textContent='Hoàn tất '+selected.length+' dòng';$('#run-desc').textContent=runMode==='preview'?'Hoàn tất chạy thử; chưa thao tác website.':mode==='register'?'Đã điền form; chưa bấm đăng ký.':cfg().saveBank?'Website đã xác nhận lưu ngân hàng.':'Đã điền thông tin ngân hàng; chưa bấm lưu.';$('#countdown').textContent='Hoàn tất · '+total+' / '+total+' bước';$('#tab-count').textContent='✓';toast(runMode==='preview'?'Hoàn tất chạy thử.':'Hoàn tất thao tác.');updateControls();
 }catch(error){if(token===runToken&&alive&&!isUnloading){phase='stopped';paused=false;clearProgress();$('#run-title').textContent='Đã dừng tại bước '+(ids[stepIndex]+1);$('#run-desc').textContent=error.message;$('#countdown').textContent='Kiểm tra trang và cấu hình trước khi chạy lại.';log('Dừng: '+error.message);toast(error.message);updateControls();}}
}

function stop(){clearProgress();if(!busy())return;runToken++;phase='stopped';paused=false;$('#countdown').textContent='Đã dừng thao tác. Chạy lại sẽ bắt đầu từ bước đầu.';$('#run-title').textContent='Đã dừng';log('Đã dừng theo yêu cầu.');updateControls();}
