function trackedPath(url){try{const p=new URL(String(url),location.href).pathname;return cfg().routes.includes(p)?p:null;}catch{return null;}}
function recordResponse(url,status,body,started){const path=trackedPath(url);if(!path)return;const code=body&&body.Code;const errors=body&&body.Error;const known=body&&typeof body==='object'&&(code!==undefined?[0,200,'0','200'].includes(code):body.Success===true||body.success===true||body.Result===true);const ok=status>=200&&status<300&&known&&!(Array.isArray(errors)&&errors.length);const msg=body&&(body.Message||body.message||(Array.isArray(errors)?errors.map(x=>typeof x==='string'?x:(x.Message||x.message||'Lỗi phản hồi')).join('; '):''));responses.push({path,ok,at:started,message:String(msg||(!known?'Chưa nhận được phản hồi JSON xác nhận thành công.':''))});if(responses.length>50)responses.shift();noteCheckpointResponse(path,ok);}
const observedFetch=async function(input,options){const started=performance.now();const response=await nativeFetch.apply(this,arguments);const url=typeof input==='string'?input:(input&&input.url);if(trackedPath(url)){response.clone().json().then(body=>recordResponse(url,response.status,body,started)).catch(()=>recordResponse(url,response.status,null,started));}return response;};
